import { notFound, ok, withHandler } from "@/lib/api";
import { requireUser } from "@/lib/auth/guards";
import { NO_STORE } from "@/lib/auth/http";
import { getDb } from "@/lib/db";
import { BOOKING_ID, getBookingDetail } from "@/lib/services/bookings";

export const dynamic = "force-dynamic";

// Spelled out instead of `RouteContext<"/api/bookings/[id]">`: that global is generated by
// `next dev`/`next build`, and CI typechecks before building.
type Context = { params: Promise<{ id: string }> };

/**
 * The owner, an admin, or an approver who may act on it (or did): the request, its decision for
 * the active timetable, approval status and a plain-language explanation (`BookingDetail`).
 * Non-admins see approvers by role label, never by user id. `404` for an unknown id or a request
 * the user may not see.
 */
export const GET = withHandler(async (request, context: Context) => {
  const user = await requireUser(request);
  const { id } = await context.params;
  if (!BOOKING_ID.test(id)) throw notFound("No booking request with that id.");
  return ok(await getBookingDetail(await getDb(), user, id), {
    headers: NO_STORE,
  });
});
